def tag_prepend_class(tag: TagT, *class_: str | None) -> TagT:
    classes = (
        *class_,
        tag.attrs.get("class"),
    )
    classes = [c for c in classes if c is not None]
    if len(classes) == 0:
        return tag
    tag.attrs["class"] = " ".join(classes)
    return tag

